INSERT INTO `evaluation` VALUES (1,1,4,'赵六',1,'张三',5,'队长非常负责，算法能力很强，带领团队取得了好成绩！','[\"负责\",\"技术强\",\"领导力\"]',1,0,'2026-05-17 23:10:00','2026-05-17 23:10:00'),(2,1,17,'李明',1,'张三',5,'张三学长很耐心指导我，学到了很多算法知识。','[\"耐心\",\"乐于助人\"]',1,0,'2026-05-17 23:10:00','2026-05-17 23:10:00'),(3,1,1,'张三',4,'赵六',4,'赵六的分布式系统知识很扎实，为团队提供了很多帮助。','[\"技术扎实\"]',1,0,'2026-05-17 23:10:00','2026-05-17 23:10:00'),(4,1,1,'张三',17,'李明',4,'李明虽然是大二，但学习能力强，进步很快。','[\"学习能力强\"]',1,0,'2026-05-17 23:10:00','2026-05-17 23:10:00'),(5,5,11,'黄三',3,'王五',5,'王五的AI技术非常专业，项目架构设计得很棒！','[\"专业\",\"架构能力强\"]',1,0,'2026-05-17 23:10:00','2026-05-17 23:10:00'),(6,5,12,'刘四',3,'王五',5,'队长对NLP方向很精通，给我们很多指导。','[\"精通技术\"]',1,0,'2026-05-17 23:10:00','2026-05-17 23:10:00'),(7,5,3,'王五',11,'黄三',5,'黄三的计算机视觉能力很强，是团队的核心成员。','[\"核心成员\",\"技术强\"]',1,0,'2026-05-17 23:10:00','2026-05-17 23:10:00'),(8,5,3,'王五',12,'刘四',4,'刘四的NLP知识很扎实，文本处理做得很好。','[\"知识扎实\"]',1,0,'2026-05-17 23:10:00','2026-05-17 23:10:00'),(9,5,9,'陈一',3,'王五',5,'王五的AI项目经验很丰富，跟着他能学到很多。','[\"经验丰富\"]',1,0,'2026-05-17 23:10:00','2026-05-17 23:10:00'),(10,6,6,'周八',2,'李四',5,'李四的前端技术很强，项目界面设计得很漂亮！','[\"前端技术强\",\"设计好\"]',1,0,'2026-05-17 23:10:00','2026-05-17 23:10:00'),(11,6,18,'王芳',2,'李四',4,'李四学长很耐心，教会我很多Vue知识。','[\"耐心\"]',1,0,'2026-05-17 23:10:00','2026-05-17 23:10:00'),(12,6,2,'李四',6,'周八',5,'周八的UI设计能力太强了，界面做得非常专业！','[\"设计专业\"]',1,0,'2026-05-17 23:10:00','2026-05-17 23:10:00'),(13,6,2,'李四',18,'王芳',4,'王芳虽然是新手，但学习能力很强，进步很快。','[\"学习能力强\"]',1,0,'2026-05-17 23:10:00','2026-05-17 23:10:00'),(14,11,9,'陈一',10,'林二',5,'林二的大数据技术非常专业，项目做得很成功！','[\"大数据专业\"]',1,0,'2026-05-17 23:10:00','2026-05-17 23:10:00'),(15,11,4,'赵六',10,'林二',5,'跟着林二学到了很多大数据知识，很有收获。','[\"乐于分享\"]',1,0,'2026-05-17 23:10:00','2026-05-17 23:10:00'),(16,11,10,'林二',9,'陈一',5,'陈一的数据分析能力很强，帮我们解决了很多难题。','[\"数据分析强\"]',1,0,'2026-05-17 23:10:00','2026-05-17 23:10:00'),(17,11,10,'林二',4,'赵六',4,'赵六的后端开发能力很扎实，数据接口做得很好。','[\"后端扎实\"]',1,0,'2026-05-17 23:10:00','2026-05-17 23:10:00'),(18,2,10,'林二',9,'陈一',5,'陈一的数学建模能力很强，是我们队的核心！','[\"数学建模强\"]',1,0,'2026-05-17 23:10:00','2026-05-17 23:10:00'),(19,2,9,'陈一',10,'林二',5,'林二的数据处理能力很强，是建模的关键。','[\"数据处理强\"]',1,0,'2026-05-17 23:10:00','2026-05-17 23:10:00'),(20,3,14,'张六',13,'何五',5,'何五的安全技术太强了，CTF比赛拿了很好的名次！','[\"安全技术强\"]',1,0,'2026-05-17 23:10:00','2026-05-17 23:10:00'),(21,3,13,'何五',14,'张六',4,'张六的运维能力很强，帮助我们搭建了训练环境。','[\"运维能力强\"]',1,0,'2026-05-17 23:10:00','2026-05-17 23:10:00');
