--
-- Table structure for table `team`
--

DROP TABLE IF EXISTS `team`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `team` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '团队ID',
  `team_name` varchar(100) NOT NULL COMMENT '团队名称',
  `description` text COMMENT '团队描述',
  `project_type` varchar(50) DEFAULT NULL COMMENT '项目类型',
  `project_name` varchar(100) DEFAULT NULL COMMENT '项目名称',
  `leader_id` bigint NOT NULL COMMENT '队长ID',
  `leader_name` varchar(50) DEFAULT NULL COMMENT '队长姓名',
  `required_members` int DEFAULT '3' COMMENT '所需人数',
  `current_members` int DEFAULT '1' COMMENT '当前人数',
  `required_skills` text COMMENT '要求技能标签（JSON数组）',
  `min_grade_point` decimal(3,2) DEFAULT NULL COMMENT '要求最低绩点',
  `min_credit_score` int DEFAULT NULL COMMENT '要求最低信誉分',
  `status` tinyint DEFAULT '0' COMMENT '状态：0-招募中，1-已满员，2-进行中，3-已完成，4-已解散',
  `deadline` datetime DEFAULT NULL COMMENT '截止日期',
  `deleted` tinyint DEFAULT '0' COMMENT '逻辑删除：0-未删除，1-已删除',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_leader_id` (`leader_id`),
  KEY `idx_status` (`status`),
  KEY `idx_deadline` (`deadline`)
) ENGINE=InnoDB AUTO_INCREMENT=44 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='团队表';
/*!40101 SET character_set_client = @saved_cs_client */;

