--
-- Table structure for table `user`
--

DROP TABLE IF EXISTS `user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '用户ID',
  `username` varchar(50) NOT NULL COMMENT '用户名（学号）',
  `password` varchar(255) NOT NULL COMMENT '密码',
  `real_name` varchar(50) NOT NULL COMMENT '真实姓名',
  `email` varchar(100) DEFAULT NULL COMMENT '邮箱',
  `phone` varchar(20) DEFAULT NULL COMMENT '手机号',
  `school` varchar(100) DEFAULT NULL COMMENT '学校',
  `grade` varchar(20) DEFAULT NULL COMMENT '年级',
  `major` varchar(100) DEFAULT NULL COMMENT '专业',
  `class_name` varchar(50) DEFAULT NULL COMMENT '班级',
  `grade_point` decimal(3,2) DEFAULT '0.00' COMMENT '绩点（0-5）',
  `credit_score` int DEFAULT '80' COMMENT '信誉分（0-100）',
  `total_score` decimal(5,2) DEFAULT '0.00' COMMENT '综合评分',
  `skill_tags` text COMMENT '技能标签（JSON数组）',
  `introduction` text COMMENT '个人简介',
  `avatar` varchar(255) DEFAULT NULL COMMENT '头像URL',
  `status` tinyint DEFAULT '1' COMMENT '状态：0-禁用，1-正常',
  `role` varchar(20) DEFAULT 'ROLE_STUDENT' COMMENT '角色标识',
  `team_intention` varchar(20) DEFAULT 'LOOKING' COMMENT '组队意向：LOOKING-寻找队友, NOT_LOOKING-暂不组队, IN_TEAM-已有团队',
  `last_login_time` datetime DEFAULT NULL COMMENT '最后登录时间',
  `deleted` tinyint DEFAULT '0' COMMENT '逻辑删除：0-未删除，1-已删除',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_username` (`username`),
  KEY `idx_grade_point` (`grade_point`),
  KEY `idx_credit_score` (`credit_score`),
  KEY `idx_total_score` (`total_score`),
  KEY `idx_team_intention` (`team_intention`),
  KEY `idx_last_login_time` (`last_login_time`)
) ENGINE=InnoDB AUTO_INCREMENT=70 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户表';
/*!40101 SET character_set_client = @saved_cs_client */;

